lemma FlatHom.ext {T : RestrictedTangentSheaf X p}
    {E F : NilpotentFlat T} (f g : FlatHom E F) (h : f.hom = g.hom) : f = g

@[ext]
lemma HiggsHom.ext {T : RestrictedTangentSheaf X p}
    {E F : NilpotentHiggs T} (f g : HiggsHom E F) (h : f.hom = g.hom) : f = g

theorem exp_mul_exp_neg_eq_one {a : A}
    (hzero : ∀ i j : ℕ, p ≤ i + j → a ^ i * (-a) ^ j = 0) :
    exp p a * exp p (-a) = 1

theorem exp_neg_mul_exp_eq_one {a : A}
    (hzero : ∀ i j : ℕ, p ≤ i + j → (-a) ^ i * a ^ j = 0) :
    exp p (-a) * exp p a = 1

theorem moduleEndExp_mul_neg_eq_one {a : Module.End R M}
    (hzero : ∀ i j : ℕ, p ≤ i + j → a ^ i * (-a) ^ j = 0) :
    moduleEndExp p a * moduleEndExp p (-a) = 1

theorem moduleEndExp_neg_mul_eq_one {a : Module.End R M}
    (hzero : ∀ i j : ℕ, p ≤ i + j → (-a) ^ i * a ^ j = 0) :
    moduleEndExp p (-a) * moduleEndExp p a = 1

lemma extensionHom_ext (U : Cᵒᵖ)
    {N : ModuleCat.{u} (B.obj U)}
    {f g : (ModuleCat.extendScalars (alpha.app U).hom).obj (M.obj U) ⟶ N}
    (h : ∀ m, f (extensionUnit alpha M U m) =
      g (extensionUnit alpha M U m)) : f = g

@[ext]
lemma ConnectionHom.ext {M N : X.IntegrableConnection}
    (f g : X.ConnectionHom M N) (h : f.hom = g.hom) : f = g

lemma tensorHomEquiv_apply {P : RingedModules R}
    (f : tensorObj R M N ⟶ P) :
    tensorHomEquiv R M N P f = tensorUnit R M N ≫ f.val

lemma foldr_replicate {T : Type u₁} {M : Type u₂}
    (act : T → M → M) (t : T) (n : ℕ) (m : M) :
    (List.replicate n t).foldr act m = (act t)^[n] m

lemma wordApply_list {T : Type u₁} {M : Type u₂}
    (act : T → M → M) (l : List T) (m : M) :
    wordApply act l.length (fun i ↦ l.get i) m = l.foldr act m
